import{_ as o,o as c,c as d,a3 as i}from"./chunks/framework.CRbjHCyB.js";const u=JSON.parse('{"title":"Feature Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"zh/clice/changelog/feature-changelog.md","filePath":"zh/clice/changelog/feature-changelog.md"}'),a={name:"zh/clice/changelog/feature-changelog.md"};function l(t,e,n,r,s,g){return c(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="feature-changelog" tabindex="-1">Feature Changelog <a class="header-anchor" href="#feature-changelog" aria-label="Permalink to &quot;Feature Changelog&quot;">​</a></h1><p>本文件记录 clice 各版本面向用户的功能变化。每个版本章节记录新功能、破坏性变更与废弃项。</p><h2 id="v1-0-0-即将发布" tabindex="-1">v1.0.0（即将发布） <a class="header-anchor" href="#v1-0-0-即将发布" aria-label="Permalink to &quot;v1.0.0（即将发布）&quot;">​</a></h2><p>v1.0 会先以滚动的测试版发布（<code>v1.0.0-beta.1</code>、<code>beta.2</code>……）公开试跑一段时间；修复以小版本持续发布、不设代码冻结窗口，试跑稳定后打正式的 <code>v1.0.0</code>。本条目汇总自 <code>v0.1.0-alpha</code> 系列以来所有用户可见的变化。</p><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>多进程架构。</strong> 编译在主进程协调下的工作子进程中执行，单个翻译单元的编译器崩溃不再拖垮整个会话——崩溃的工作进程会被重新拉起，其负责的文档按需恢复。有状态工作进程以 LRU 淘汰驻留文档，进程池在系统内存压力下会卸载后台负载。</li><li><strong>头文件的编译上下文。</strong> 打开头文件时，clice 会在某个包含它的源文件的上下文中编译它：重建 include 链合成 preamble（对 X-macro/<code>.def</code> 片段还会合成 suffix），使依赖 includer 宏的符号正确解析。编辑器可以通过 <code>clice/queryContext</code>、<code>clice/currentContext</code>、<code>clice/switchContext</code> 扩展列出并切换活跃上下文——同一机制也用于在一个文件的多个编译数据库条目之间切换。自包含的头文件会被识别并直接编译。</li><li><strong>LSP 功能面。</strong> Hover（定义打印、文档注释、含 size/offset/padding 的结构布局、表达式求值、<code>auto</code>/<code>decltype</code> 推导）；带签名详情、参数 snippet、废弃符号删除线以及 <code>#include</code>/<code>import</code> 路径补全的代码补全；签名帮助；跳转到定义（含 <code>#include</code> 行与模块名）、声明、实现、类型定义与查找引用（由项目索引提供）；文档符号；带丰富修饰符的语义高亮；inlay hints；折叠区间；文档链接（含 preamble 内与 <code>#embed</code>）；基于 <code>.clang-format</code> 的全文与区间格式化；调用层级与类型层级；工作区符号搜索；诊断发布；<code>#if</code> 关闭代码的置灰（<code>clice/inactiveRegions</code> 扩展）。</li><li><strong>后台索引。</strong> 持久化的项目级索引支撑跨文件功能，无需逐个打开文件。索引搭编译的便车、以低优先级并发执行、遇到交互请求会让路、通过 LSP <code>$/progress</code> 汇报进度，并跨重启复用。两层过期检测（先 mtime 后内容哈希）使 <code>touch</code> 和 <code>git checkout</code> 不会触发无谓重建。</li><li><strong>编辑器之外的变化追踪。</strong> stat 轮询的文件追踪器可以发现编辑器外发生的变化——重新生成的 <code>compile_commands.json</code>、<code>git checkout</code>、代码生成器——无需重启服务器。</li><li><strong>C++20 命名模块。</strong> 模块接口经由拉取式依赖图按需编译并缓存 PCM；支持 <code>import</code> 补全与模块名上的跳转定义。</li><li><strong>统一磁盘缓存。</strong> PCH、PCM 与索引产物存放在同一个内容寻址存储中，写入崩溃安全，跨会话与重启复用；可重建的产物（PCH/PCM）按大小上限淘汰。</li><li><strong>配置。</strong> <code>clice.toml</code>（或 <code>.clice/config.toml</code>）加 LSP <code>initializationOptions</code> 覆盖；带 glob 模式的按文件 <code>[[rules]]</code> 追加/移除编译标志；<code>[tracker]</code> 轮询间隔；基于 XDG 的缓存路径与 <code>${workspace}</code> 替换。配置文件格式错误会以带行列号的诊断报告在配置文件上。</li><li><strong>工具 API。</strong> 面向 AI agent 与外部工具的 TCP JSON-RPC API：项目文件、符号搜索、读取完整符号体、定义/引用、调用图、类型层级——以及 <code>clice query</code> 命令行。</li><li><strong>编辑器扩展。</strong> 仓库内维护的 VS Code（已发布到 Marketplace）、Neovim 与 Zed 扩展。</li><li><strong>可运维性。</strong> 按会话的文件日志与崩溃现场捕获；环境有问题（如找不到编译数据库）时通过 <code>window/logMessage</code> 给出指引；LSP 会话录制回放（<code>--record</code>）；<code>--version</code> 输出与发布 tag 一致。</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>配置文件位置。</strong> <code>config</code> 命令行选项已移除；配置从 <code>${workspace}/clice.toml</code>（或 <code>${workspace}/.clice/config.toml</code>）读取。</li><li><strong>配置键更名。</strong> <code>compile_commands_dirs</code> 更名为 <code>compile_commands_paths</code>；旧键会被忽略。</li><li><strong>从 0.x 升级会重建缓存。</strong> 磁盘缓存与索引格式已变化；升级后首次启动会丢弃旧产物并对项目重新索引一次。这同时淘汰了旧版本生成的 PCH——旧缓存键不含编译标志，可能用错误的宏配置提供结果。</li><li><strong>工具链基线。</strong> clice 现基于 LLVM/Clang 21.1.8 构建，并为 Linux、macOS、Windows 的 x64 与 arm64 提供预编译二进制。</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>快速连续编辑不再因编译/更新竞态产生虚假的&quot;重定义&quot;错误。</li><li>修复了多个畸形输入导致的工作进程崩溃（空 AST consumer、无效文件 ID、缺失缓存目录）；仍发生的崩溃由进程隔离兜住。</li><li>被工作进程 LRU 淘汰的文档不再无声失去 hover/语义高亮——下次请求时重新编译。</li><li>生命周期边界：早于 <code>initialize</code> 握手到达的 <code>didOpen</code> 会被受理；较新 LSP 客户端的未知枚举值不再导致握手失败；客户端就绪前产生的诊断会在 <code>initialized</code> 后补发。</li><li>保存头文件现在会正确地重索引包含它的已关闭文件，保持跨文件引用最新。</li></ul><h3 id="known-gaps" tabindex="-1">Known gaps <a class="header-anchor" href="#known-gaps" aria-label="Permalink to &quot;Known gaps&quot;">​</a></h3><ul><li>代码补全、导航、文档链接与诊断可用但尚不完整（各功能状态见 feature overview 页面）。</li><li>Code action 尚未实现（也未在 capabilities 中宣告）。</li><li>clang-tidy 集成在计划中；<code>clang_tidy</code> 配置项会被解析但当前无效果。</li></ul>',12)])])}const m=o(a,[["render",l]]);export{u as __pageData,m as default};
